									break;
									// Если мы нашли переменную (j)
									case 'j': {
										// Выполняем обработку полученных данных
										pos = this->prepare(this->_dt, date, format_t::j, pos);
										// Устанавливаем флаг установки номера дня в году
										flags[8] = (pos > -1);
									} break;
									// Если мы нашли переменную (u)
									case 'u':
										// Выполняем обработку полученных данных
